import{_ as o,o as i,c as a,a2 as r}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"Runbook degli incidenti","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/runbook.md","filePath":"admin-guide/runbook.md"}'),n={name:"admin-guide/runbook.md"};function l(t,e,c,d,s,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="runbook-degli-incidenti" tabindex="-1">Runbook degli incidenti <a class="header-anchor" href="#runbook-degli-incidenti" aria-label="Permalink to &quot;Runbook degli incidenti&quot;">​</a></h1><p>Formato: <strong>sintomo → verifica → rimedio</strong>. Prima di ogni caso, i tre strumenti base:</p><ul><li>log del servizio (JSON, un <code>request_id</code> per richiesta; il client invia <code>X-Request-Id</code>): <code>kubectl logs deploy/clarae-api</code>, <code>kubectl logs deploy/clarae-worker</code>;</li><li><code>GET /api/v1/healthz</code> (processo vivo) e <code>GET /api/v1/readyz</code> (database e storage rispondono entro 3 s; risponde 503 e, solo se interrogato direttamente dalla rete interna, ad esempio con <code>kubectl port-forward deploy/clarae-api 18081</code> o <code>docker compose exec proxy wget -qO- http://cloud-api:18081/api/v1/readyz</code>, il nome e l&#39;errore della dipendenza che manca; da fuori, il dettaglio è nel log <code>readiness check failed</code>). Per il worker: <code>/healthz</code> e <code>/readyz</code> sulla porta 18083 (<code>state</code>: <code>running</code>, <code>waiting-for-schema</code>, <code>stalled</code>);</li><li>dashboard Grafana &quot;Panoramica servizio cloud&quot; (<a href="./monitoraggio.html">monitoraggio</a>) e registro di audit della console admin.</li></ul><h2 id="il-login-non-funziona" tabindex="-1">Il login non funziona <a class="header-anchor" href="#il-login-non-funziona" aria-label="Permalink to &quot;Il login non funziona&quot;">​</a></h2><p><strong>Sintomo:</strong> il browser o l&#39;app desktop non completano l&#39;accesso; l&#39;API risponde <code>401</code>; la Web UI mostra &quot;configurazione non disponibile&quot;.</p><ol><li><code>curl -s https://&lt;host&gt;/api/v1/client-config</code>: deve restituire issuer e client id. Se manca o l&#39;issuer è sbagliato, controllare <code>OIDC_ISSUER</code> (deve coincidere <strong>esattamente</strong> con il claim <code>iss</code> dei token, incluso <code>/realms/clarae</code>).</li><li>Il servizio raggiunge Keycloak? Dal pod: <code>curl -s $OIDC_ISSUER/.well-known/openid-configuration</code>. Al riavvio il servizio recupera le chiavi JWKS: se Keycloak è giù il processo non parte (<code>connectOIDC</code> nei log).</li><li><code>401</code> con token valido: verificare <code>aud</code> (<code>OIDC_AUDIENCE</code>, default <code>clarae-api</code>) e <code>azp</code> (<code>OIDC_ALLOWED_AZP</code>). Nel realm il client scope deve aggiungere l&#39;audience <code>clarae-api</code>.</li><li>Scarto dell&#39;orologio: i token sono validati con il tempo del server; sincronizzare NTP su nodi e Keycloak.</li><li>Desktop: il redirect loopback fallisce o è bloccato dal firewall → l&#39;app ripiega su <code>clarae://auth/callback</code>; verificare che lo scheme sia registrato (installer) e che il client <code>clarae-desktop</code> ammetta entrambi i redirect.</li><li>Web UI: l&#39;origine deve essere in <code>WEB_UI_ORIGIN</code> (CORS) e tra i redirect URI del client <code>clarae-web</code>.</li><li>Un solo utente non entra: potrebbe essere sospeso (vedi sotto) oppure bloccato da Keycloak (Utenti → stato, brute-force detection).</li></ol><p><strong>Rimedio:</strong> correggere la variabile o il realm, riavviare l&#39;API (<code>kubectl rollout restart deploy/clarae-api</code>).</p><h2 id="un-utente-riceve-409-invalid-state-a-ogni-richiesta" tabindex="-1">Un utente riceve 409 INVALID_STATE a ogni richiesta <a class="header-anchor" href="#un-utente-riceve-409-invalid-state-a-ogni-richiesta" aria-label="Permalink to &quot;Un utente riceve 409 INVALID_STATE a ogni richiesta&quot;">​</a></h2><p><strong>Sintomo:</strong> un utente riesce ad autenticarsi in Keycloak ma ogni chiamata all&#39;API risponde <code>409</code> con codice <code>INVALID_STATE</code> e il messaggio &quot;this sign-in cannot be linked to your Clarae account…&quot;.</p><ol><li>È un conflitto di identità (vedi <a href="./keycloak.html#ruoli-di-realm">Keycloak</a>): l&#39;e-mail del token appartiene già a un altro account Clarae notanda non eliminato, collegato a un altro <code>sub</code> (tipicamente un account Keycloak eliminato e ricreato).</li><li>Console → <strong>Utenti</strong>, cercare l&#39;e-mail: compare l&#39;account precedente (attivo o sospeso).</li></ol><p><strong>Rimedio:</strong> se l&#39;account precedente è della stessa persona e non serve più, eliminarlo dalla console (i suoi vault entrano nel periodo di conservazione); altrimenti cambiarne l&#39;e-mail dalla console. Il nuovo accesso si collega alla richiesta successiva, al più dopo <code>OIDC_STATUS_CACHE_TTL</code> (il rifiuto è memorizzato per quel tempo per non interrogare il database a ogni tentativo). Per recuperare i vault dell&#39;account precedente non c&#39;è una funzione di ricollegamento: va chiesto all&#39;utente di esportarli prima dell&#39;eliminazione.</p><h2 id="la-sincronizzazione-e-bloccata-o-lenta" tabindex="-1">La sincronizzazione è bloccata o lenta <a class="header-anchor" href="#la-sincronizzazione-e-bloccata-o-lenta" aria-label="Permalink to &quot;La sincronizzazione è bloccata o lenta&quot;">​</a></h2><p><strong>Sintomo:</strong> i client mostrano &quot;sync in corso&quot; a lungo, errori di rete, o le modifiche arrivano in ritardo.</p><ol><li>Dashboard → <em>Sincronizzazione</em>: commit/s con <code>outcome=&quot;error&quot;</code> &gt; 0? Latenza p95 alta? Pool del database saturo?</li><li><code>rejected</code> in aumento: leggere il campo <code>code</code> nelle risposte (<code>QUOTA_EXCEEDED</code>, <code>PATH_COLLISION</code>, <code>VAULT_ENCRYPTED</code>…): non è un guasto ma una regola; vedi <a href="#quota-esaurita">Quota esaurita</a>.</li><li>Solo notifiche in ritardo: lo stream (gRPC o SSE) può essere interrotto da proxy. Dopo una caduta della connessione <code>LISTEN</code> verso PostgreSQL (failover, riavvio) il servizio si ricollega da solo e riallinea gli stream aperti dal database (log <code>notify listener reconnected</code> e <code>notify: subscribers resynced</code>): le notifiche emesse nel frattempo arrivano come posizioni aggiornate dei vault. Un utente può aprire al massimo 32 stream per replica (gli ulteriori sono rifiutati con <code>RESOURCE_EXHAUSTED</code> su gRPC o <code>429</code> su SSE) e ogni connessione gRPC viene chiusa e riaperta dal client ogni 30 minuti circa, così le connessioni si ridistribuiscono tra le repliche. Verificare <code>clarae_notify_streams_active</code> e che l&#39;ingress inoltri HTTP/2 per gRPC (host dedicato <code>grpcHost</code> nel chart); il client ripiega su SSE e su un polling periodico, quindi il ritardo è limitato ma non nullo.</li><li>Un solo vault: confrontare <code>last_seq</code> del vault (pagina Vault utente nella console) con il cursore dei client; un client rimasto indietro oltre <code>sync.changelog_window_days</code> riparte dal manifesto (comportamento normale, più lento).</li><li>Un file in conflitto continuo: il merge è sul client; per i tipi diversi da <code>.md</code> il server produce copie di conflitto. Nessun dato viene perso (le versioni scartate restano nello storico).</li><li>Blocchi sul database: query lente o lock (<code>pg_stat_activity</code>); il commit tiene lock di riga sul proprietario del vault (quota) per microsecondi, un lock prolungato indica una transazione ferma.</li></ol><p><strong>Rimedio:</strong> aumentare repliche API o <code>max_connections</code>, correggere l&#39;ingress, riavviare lo stream; per un client bloccato basta &quot;Sincronizza ora&quot; o riavviare l&#39;app (lo stato è in <code>sync.db</code>, l&#39;operazione è idempotente grazie agli <code>op_id</code>).</p><h2 id="quota-esaurita" tabindex="-1">Quota esaurita <a class="header-anchor" href="#quota-esaurita" aria-label="Permalink to &quot;Quota esaurita&quot;">​</a></h2><p><strong>Sintomo:</strong> gli utenti ricevono <code>QUOTA_EXCEEDED</code>; la barra dell&#39;utilizzo nella Web UI è rossa (soglie <code>warn_percent</code>/<code>critical_percent</code>).</p><ol><li>Console → <strong>Archiviazione</strong>: utenti sopra soglia e principali consumatori. La quota conta <strong>solo i file correnti</strong>, non lo storico (D-03) ed è addebitata al <strong>proprietario</strong> del vault condiviso.</li><li>Se il dato sembra sbagliato, la riconciliazione notturna (<code>maintenance</code>) corregge le derive: forzarla con un riavvio del worker non è necessario; controllare nei log del worker <code>usage drift corrected</code>.</li><li>Vault eliminati non ancora purgati occupano spazio fino a <code>vaults.deleted_retention_days</code>.</li></ol><p><strong>Rimedio:</strong> aumentare la quota dell&#39;utente (console → Utenti → <em>Cambia quota</em>, o quota in blocco dalla lista), aumentare il default in <strong>Limiti</strong>, oppure chiedere all&#39;utente di eliminare file. Ogni modifica è nel registro di audit (<code>user.quota</code>).</p><h2 id="utente-sospeso" tabindex="-1">Utente sospeso <a class="header-anchor" href="#utente-sospeso" aria-label="Permalink to &quot;Utente sospeso&quot;">​</a></h2><p><strong>Sintomo:</strong> un utente non riesce più a usare l&#39;API (errore di account sospeso) pur avendo un token valido.</p><ol><li>Console → Utenti → stato <code>Sospeso</code>. L&#39;azione è nel registro di audit (<code>user.suspend</code>, con attore e IP).</li><li>La sospensione ha effetto entro <code>OIDC_STATUS_CACHE_TTL</code> (30 s): il servizio controlla <code>users.status</code> oltre alla validità del token. Una sospensione non revoca i token già emessi in Keycloak, li rende inutilizzabili sull&#39;API.</li><li>Gli stream di notifica attivi si chiudono al successivo controllo; i client mostrano &quot;account sospeso&quot; e non perdono i dati locali.</li></ol><p><strong>Rimedio:</strong> <em>Riattiva</em> dalla console (<code>user.activate</code>). Se la sospensione è stata fatta su Keycloak e non nella console, riabilitare l&#39;utente lì.</p><h2 id="gli-export-restano-in-coda" tabindex="-1">Gli export restano in coda <a class="header-anchor" href="#gli-export-restano-in-coda" aria-label="Permalink to &quot;Gli export restano in coda&quot;">​</a></h2><p><strong>Sintomo:</strong> il download ZIP di un vault condiviso resta su &quot;in coda&quot; o &quot;in preparazione&quot;; stato <code>failed</code> o <code>expired</code>.</p><ol><li>Gli export sono eseguiti dal job <code>exports</code> (ogni 15 s) in un processo con <code>--role=worker</code> o <code>--role=all</code>. Se tutte le repliche sono <code>--role=api</code>, <strong>nessuno</strong> li elabora: aggiungere un worker. Un worker con <code>/readyz</code> a 503 e <code>state</code> <code>waiting-for-schema</code> non esegue job finché l&#39;API non ha migrato il database (log <code>waiting for the API to migrate the database schema</code>): verificare che almeno una replica API della stessa versione sia partita.</li><li>Il worker sfrattato (<code>Evicted</code>, <code>ephemeral-storage</code>) ha superato <code>worker.tmp.sizeLimit</code> costruendo un archivio: alzare il limite (e <code>resources.limits.ephemeral-storage</code>) sopra la dimensione del vault più grande.</li><li>Dashboard → <em>Job</em>: <code>clarae_jobs_runs_total{exported_job=&quot;exports&quot;,result=&quot;error&quot;}</code> (<code>job</code> con <code>honor_labels: true</code>) e &quot;Tempo dall&#39;ultimo successo&quot;. Nei log del worker cercare <code>job failed</code> con <code>job=exports</code>.</li><li>Cause tipiche: bucket <code>S3_BUCKET_EXPORTS</code> inesistente o credenziali senza scrittura; disco o quota dell&#39;archivio pieni; vault molto grande che supera il tempo (il job ritenta alla successiva esecuzione).</li><li><code>expired</code>: l&#39;archivio è stato rimosso dopo il periodo di validità; l&#39;utente deve ripetere la richiesta.</li><li>I vault <strong>privati</strong> non si esportano dal server (<code>409 VAULT_ENCRYPTED</code>): lo ZIP si costruisce nel browser dopo aver inserito passphrase o recovery key. Se &quot;non funziona&quot;, verificare che l&#39;utente conosca la passphrase: non esiste recupero lato server.</li></ol><p><strong>Rimedio:</strong> correggere bucket e credenziali, riavviare il worker; l&#39;utente rilancia l&#39;export dalla Web UI.</p><h2 id="il-servizio-non-risponde-o-il-database-e-giu" tabindex="-1">Il servizio non risponde o il database è giù <a class="header-anchor" href="#il-servizio-non-risponde-o-il-database-e-giu" aria-label="Permalink to &quot;Il servizio non risponde o il database è giù&quot;">​</a></h2><p><strong>Sintomo:</strong> <code>readyz</code> risponde 503 con <code>database</code>, errori 5xx, allarmi <code>ClaraeDown</code> / <code>ClaraeDbPoolSaturated</code>.</p><ol><li><code>kubectl get pods</code>; <code>kubectl describe pod</code> (OOMKilled? probe fallite?); <code>kubectl logs --previous</code>.</li><li>Database: raggiungibile dal pod? (<code>psql &quot;$DATABASE_URL&quot; -c &#39;select 1&#39;</code>), spazio su disco, <code>max_connections</code>, failover in corso. Il servizio non perde dati se il DB è momentaneamente giù: restituisce errori e i client riprovano con backoff; i commit sono idempotenti.</li><li>Saturazione del pool: dashboard → <em>Database</em>. Il pool è dimensionato dalla libreria; con molte repliche la somma delle connessioni può superare <code>max_connections</code> di PostgreSQL (usare un pooler come PgBouncer in modalità session; <strong>non</strong> transaction se si usano <code>LISTEN/NOTIFY</code> — lo stream di notifica ne ha bisogno).</li><li>Migrazioni fallite all&#39;avvio: il pod resta in crash loop con l&#39;errore di goose (con più repliche, una sola migra alla volta sotto advisory lock: le altre attendono fino a 10 minuti e, se il lock non si libera, falliscono con <code>failed to acquire lock</code>); non avviare versioni precedenti sul DB migrato (vedi <a href="./backup-upgrade.html">upgrade</a>).</li></ol><p><strong>Rimedio:</strong> ripristinare il database (da backup o replica, <a href="./backup-upgrade.html">backup</a>), poi <code>kubectl rollout restart</code>. Al ritorno del DB i client si riallineano da soli.</p><h2 id="l-archivio-s3-non-e-raggiungibile" tabindex="-1">L&#39;archivio S3 non è raggiungibile <a class="header-anchor" href="#l-archivio-s3-non-e-raggiungibile" aria-label="Permalink to &quot;L&#39;archivio S3 non è raggiungibile&quot;">​</a></h2><p><strong>Sintomo:</strong> <code>readyz</code> 503 con <code>storage</code>; upload e download di blob falliscono; gli export non si completano.</p><ol><li>Raggiungibilità e credenziali: <code>aws --endpoint-url $S3_ENDPOINT s3 ls s3://clarae-blobs</code> con le chiavi del Secret; certificato TLS valido; regola CORS se si usa <code>S3_PUBLIC_ENDPOINT</code>.</li><li>Bucket esistenti con i nomi di <code>S3_BUCKET_BLOBS</code> e <code>S3_BUCKET_EXPORTS</code>; spazio e quota del provider.</li><li>I metadati (database) e i blob sono separati: con S3 giù i client possono ancora scaricare l&#39;elenco delle modifiche, ma non i contenuti; le scritture riprovano. Il GC dei blob <strong>non</strong> cancella nulla se la cancellazione dell&#39;oggetto fallisce (prima l&#39;oggetto, poi la riga): nessuna incoerenza.</li><li>Dopo un ripristino parziale dello storage: la riconciliazione notturna dei riferimenti blob (<code>blob ref count corrected</code> nei log) corregge i contatori, ma non può ricreare oggetti mancanti. Un oggetto mancante appare come errore di download di un file specifico: ripristinarlo dal backup dello storage.</li></ol><p><strong>Rimedio:</strong> ripristinare la connettività o le credenziali; nessun riavvio necessario se il provider torna disponibile.</p><h2 id="raccogliere-informazioni-per-un-escalation" tabindex="-1">Raccogliere informazioni per un&#39;escalation <a class="header-anchor" href="#raccogliere-informazioni-per-un-escalation" aria-label="Permalink to &quot;Raccogliere informazioni per un&#39;escalation&quot;">​</a></h2><p>Versione (<code>GET /api/v1/healthz</code> e log di avvio), orario e <code>request_id</code> della richiesta fallita, estratto dei log API/worker, screenshot della dashboard, esito di <code>readyz</code>, versione di Keycloak e PostgreSQL. Non allegare token, segreti o contenuto delle note.</p>',37)])])}const m=o(n,[["render",l]]);export{g as __pageData,m as default};
